test("capitalizing", || {
    check_eq(capitalize_words("élan VITAL"), "Élan Vital");
    check_eq(capitalize_words("  the   quick fox "), "The Quick Fox");
    check_eq(capitalize_words(""), "");
});

test("palindromes", || {
    check(is_palindrome("A man, a plan, a canal: Panama"));
    check(is_palindrome("Été"));
    check(!is_palindrome("hello"));
    check(is_palindrome(""));
});

test("truncating safely", || {
    check_eq(truncate("Grüße aus Köln", 6), "Grüße…");
    check_eq(truncate("short", 10), "short");
    check_eq(truncate("🦀🦀🦀", 2), "🦀…");
    check_eq(truncate("abc", 0), "");
    check_eq(truncate("abc", 3), "abc");
});

test("run lengths", || {
    check_eq(run_lengths("aaabcc"), "a3bc2");
    check_eq(run_lengths("ééé!"), "é3!");
    check_eq(run_lengths(""), "");
});

test("reversing words", || {
    check_eq(reverse_words("one two  three"), "three two one");
    check_eq(reverse_words("solo"), "solo");
});

